S('12. Restriction cards A to L (campaign)');
function con(letter,fn){game(32,4);rig([[B(2,0),B(5,0),B(8,0),B(11,0),YL(4)],[B(2,1),B(5,1),B(8,1),B(11,1),YL(8)],[B(3),B(4),B(9)],[B(6),B(7),B(10)]]);X.G.ms.gcon=null;X.G.seats[0].con=letter;act(0);fn()}
const cutV=(v,st)=>({a:'dual',st:st==null?1:st,ks:[sl(st==null?1:st).findIndex(x=>E.cv(x.id)===v)],v});
R('Restriction A: you may only cut even values.',()=>{con('A',()=>{no(cutV(5),0);must(cutV(8),0)})});
R('Restriction B: you may only cut odd values.',()=>{con('B',()=>{no(cutV(8),0);must(cutV(5),0)})});
R('Restriction C: you may only cut values 1 to 6.',()=>{con('C',()=>{no(cutV(8),0);no(cutV(11),0);must(cutV(5),0)})});
R('Restriction D: you may only cut values 7 to 12.',()=>{con('D',()=>{no(cutV(5),0);must(cutV(8),0)})});
R('Restriction E: you may only cut values 4 to 9.',()=>{con('E',()=>{no(cutV(2),0);no(cutV(11),0);must(cutV(5),0)})});
R('Restriction F: you may NOT cut values 4 to 9.',()=>{con('F',()=>{no(cutV(5),0);no(cutV(8),0);must(cutV(2),0)})});
R('Restriction G: no equipment cards and no personal item.',()=>{con('G',()=>{ready('eq6');X.G.dial=2;no({a:'eq',id:'eq6'},0);no({a:'dual',st:1,ks:[0,1],v:2,tool:'dd'},0)})});
R('Restriction H: a failed cut places no token; you may not cut a wire that has a token; no Sticky Note.',()=>{con('H',()=>{ready('eq4');no({a:'eq',id:'eq4',s:0,k:1},0);const d=X.G.dial;must({a:'dual',st:1,ks:[sl(1).findIndex(x=>E.cv(x.id)===8)],v:5},0);
  exp([X.G.dial,sl(1).every(x=>!x.tok.length)],[d-1,true],'[dial,no token]');act(0);sl(1)[0].tok.push({t:'n',v:2});no({a:'dual',st:1,ks:[0],v:2},0)})});
R('Restriction I: you may not cut the right-most wire of a teammate\'s stand.',()=>{con('I',()=>{const last=sl(1).length-1;no({a:'dual',st:1,ks:[last],v:5},0);must({a:'dual',st:1,ks:[K(1,B(5,1))],v:5},0)})});
R('Restriction J: you may not cut the left-most wire of a teammate\'s stand.',()=>{con('J',()=>{no({a:'dual',st:1,ks:[0],v:2},0);must({a:'dual',st:1,ks:[K(1,B(5,1))],v:5},0)})});
R('Restriction K: you may not Solo Cut.',()=>{game(32,4);rig([[B(7,0),B(7,1),B(7,2),B(7,3),B(1)],[B(2)],[B(3)],[B(4)]]);X.G.ms.gcon=null;X.G.seats[0].con='K';act(0);no({a:'solo',v:7},0)});
R('Restriction L: if your cut fails the fuse advances 2 steps instead of 1.',()=>{con('L',()=>{const d=X.G.dial;must({a:'dual',st:1,ks:[sl(1).findIndex(x=>E.cv(x.id)===8)],v:5},0);exp(X.G.dial,d-2,'dial')})});
R('Restrictions never stop Reveal Reds, and yellow breaks A to E and passes F.',()=>{game(32,4);rig([[RD(3),RD(5)],[B(5,1),B(2)],[B(3)],[B(7)]]);X.G.ms.gcon=null;X.G.seats[0].con='A';act(0);must({a:'reveal'},0);
  con('A',()=>no({a:'dual',st:1,ks:[sl(1).findIndex(x=>E.cv(x.id)==='Y')],v:'Y'},0));con('F',()=>must({a:'dual',st:1,ks:[sl(1).findIndex(x=>E.cv(x.id)==='Y')],v:'Y'},0))},{src:'G'});

// =====================================================================================
S('13. Challenge cards 1 to 10 (campaign)');
function chal(id,stands,hist){game(55,4);rig(stands);X.G.dial=3;X.G.ms.chal=[{id,nums:id===8?[5,6]:undefined}];X.G.ms.chalOut=[];X.G.ms.chalDone=[];X.G.hist=hist||[];act(0)}
// stand 2 gets `ids` (sorted), the listed indexes already cut; seat 0 then cuts `finalId` on stand 2 by naming value `v`
function chalCut(id,ids,pre,finalId,v){chal(id,[[B(v,1),B(12,3)],[B(11,3)],ids,[B(10,3)]]);pre.forEach(k=>{sl(2)[k].cut=1});X.G.tot[v]=(X.G.tot[v]||0);
  const stage=sl(2).filter(x=>x.cut).map(x=>E.cv(x.id));for(const c of stage)X.G.tot[c]=(X.G.tot[c]||0);must({a:'dual',st:2,ks:[K(2,finalId)],v},0)}
const done=()=>!!(X.G.ms.chalDone.length||X.G.ms.chal.length===0);
const H=(kind,v,seat)=>({seat:seat==null?0:seat,kind,v,ok:1,turn:1});
R('Challenge 1: point at a wire and say "red" instead of an action; if red it is revealed and the challenge met, otherwise boom.',()=>{
  const g=(red)=>{chal(1,[[B(1)],[red?RD(3):B(3),B(4)],[B(5)],[B(6)]]);return mv({a:'redcall',s:1,k:0},0)};
  const r=g(true);yes(r.success,'red call accepted',r.error);yes(done()&&!X.G.over,'challenge met, no explosion',J(X.G.over));g(false);exp(X.G.over&&X.G.over.win,false,'explodes when not red')});
R('Challenge 2: 4 turns in a row each cut an even value.',()=>{chal(2,[[B(2,0),B(8,0),B(1)],[B(2,1),B(8,1),B(3)],[B(4)],[B(6)]],[H('dual',6),H('dual',4),H('solo',10)]);must({a:'dual',st:1,ks:[K(1,B(2,1))],v:2},0);yes(done(),'challenge met after the 4th even cut','not met')});
R('Challenge 3: on some stand the uncut wires form only separate pairs (exactly 2 side by side, split by cut wires).',()=>{
  chalCut(3,[B(1),B(2),B(3),B(4),B(5),B(6)],[2],B(6,0),6);yes(done(),'uncut wires 1-2 and 4-5 are only pairs','not met')});
R('Challenge 3 is not met while a run of three or one uncut wire remains.',()=>{chalCut(3,[B(1),B(2),B(3),B(4),B(5),B(6),B(7)],[2],B(7,0),7);yes(!done(),'runs 2 and 3 are not all pairs','met')});
R('Challenge 4: the first 3 validation tokens placed add up to 18.',()=>{
  chal(4,[[B(7,1),B(7,0),B(1)],[B(7,2),B(7,3),B(2)],[B(3)],[B(4)]]);X.G.valid=[5,6];X.G.fin[5]=1;X.G.fin[6]=1;sl(0)[K(0,B(7,0))].cut=1;sl(1)[K(1,B(7,2))].cut=1;
  must({a:'dual',st:1,ks:[K(1,B(7,3))],v:7},0);exp(X.G.valid,[5,6,7],'validation tokens');yes(done(),'5+6+7=18 meets it','not met')});
R('Challenge 4 fails for good if the first three tokens do not add up to 18.',()=>{
  chal(4,[[B(7,1),B(7,0),B(1)],[B(7,2),B(7,3),B(2)],[B(3)],[B(4)]]);X.G.valid=[5,6];X.G.fin[5]=1;X.G.fin[6]=1;X.G.valid=[1,2];sl(0)[K(0,B(7,0))].cut=1;sl(1)[K(1,B(7,2))].cut=1;
  must({a:'dual',st:1,ks:[K(1,B(7,3))],v:7},0);yes(!done(),'1+2+7=10 does not meet it','met')});
R('Challenge 5: two turns in a row are Solo Cuts.',()=>{chal(5,[[B(7,0),B(7,1),B(7,2),B(7,3)],[B(1)],[B(2)],[B(3)]],[H('solo',4,3)]);must({a:'solo',v:7},0);yes(done(),'second solo in a row meets it','not met')});
R('Challenge 5 needs the two solos in a row: a dual cut in between breaks the chain.',()=>{chal(5,[[B(7,0),B(7,1),B(7,2),B(7,3)],[B(1)],[B(2)],[B(3)]],[H('solo',4,3),H('dual',2,2)]);must({a:'solo',v:7},0);yes(!done(),'solo, dual, solo is not two in a row','met')});
R('Challenge 6: on a single stand at least 5 uncut wires each sit alone between cut wires or a stand end.',()=>{
  chalCut(6,[B(1),B(2),B(3),B(4),B(5),B(6),B(7),B(8),B(9),B(10,0)],[1,3,5,7],B(10,0),10);yes(done(),'uncut 1,3,5,7,9 are each alone','not met')});
R('Challenge 7: 3 turns in a row cut consecutive values (ascending or descending).',()=>{chal(7,[[B(10,0),B(1)],[B(10,1),B(2)],[B(3)],[B(4)]],[H('dual',8),H('dual',9)]);must({a:'dual',st:1,ks:[K(1,B(10,1))],v:10},0);yes(done(),'8-9-10 meets it','not met')});
R('Challenge 7 also accepts a descending run (5-4-3).',()=>{chal(7,[[B(3,0),B(1)],[B(3,1),B(2)],[B(6)],[B(4)]],[H('dual',5),H('dual',4)]);must({a:'dual',st:1,ks:[K(1,B(3,1))],v:3},0);yes(done(),'5-4-3 meets it','not met')});
R('Challenge 8: two number cards are placed on it; met if the first 2 validation tokens placed are exactly those two values.',()=>{
  chal(8,[[B(6,1),B(6,0),B(1)],[B(6,2),B(6,3),B(2)],[B(3)],[B(4)]]);X.G.valid=[5];X.G.fin[5]=1;sl(0)[K(0,B(6,0))].cut=1;sl(1)[K(1,B(6,2))].cut=1;
  must({a:'dual',st:1,ks:[K(1,B(6,3))],v:6},0);exp(X.G.valid,[5,6],'validation tokens');yes(done(),'tokens 5 and 6 meet it','not met')});
R('Challenge 8 fails if the first two tokens are other values.',()=>{
  chal(8,[[B(8,1),B(8,0),B(1)],[B(8,2),B(8,3),B(2)],[B(3)],[B(4)]]);X.G.valid=[5];X.G.fin[5]=1;sl(0)[K(0,B(8,0))].cut=1;sl(1)[K(1,B(8,2))].cut=1;
  must({a:'dual',st:1,ks:[K(1,B(8,3))],v:8},0);yes(!done(),'5 and 8 do not match 5 and 6','met')});
R('Challenge 9: one stand holds only odd uncut blue wires, at least 6 of them (red and yellow ignored).',()=>{
  chalCut(9,[B(1),B(2,0),B(3),B(5),B(7),B(9),B(11),RD(4)],[],B(2,0),2);yes(done(),'six odd blues, a red ignored, after the 2 is cut','not met')});
R('Challenge 10: on one stand at least 7 wires are cut while the wire at each end is still uncut.',()=>{
  chalCut(10,[B(1),B(2),B(3),B(4),B(5),B(6),B(7),B(8,0),B(9)],[1,2,3,4,5,6],B(8,0),8);yes(done(),'7 cut with both ends uncut','not met')});
R('A met challenge is discarded and the fuse turns back 1 step.',()=>{chal(7,[[B(10,0),B(1)],[B(10,1),B(2)],[B(3)],[B(4)]],[H('dual',8),H('dual',9)]);const d=X.G.dial;must({a:'dual',st:1,ks:[K(1,B(10,1))],v:10},0);exp([X.G.dial,done()],[d+1,true],'[dial,discarded]')});

// =====================================================================================
S('14. Communication (not testable in the engine)');

// ---------- runner ----------
const md=process.argv.includes('--md');
if(md){let cur='';const out=['# Short Fuse: rules checklist','','Generated by `node logic-test.js --md`. Every item is a rule of the published rulebook, written in our own words. `logic-test.js` has one assertion per number. Source tag: C = confirmed from rulebook, FAQ or printed cards; G = our reading where the rulebook is silent.','',
  'Short Fuse adapts a real-time-free co-op bomb-defusal wire game, so the numbered items below replace the generic card-game list (draw pile, nopes, defuse cards): this game has stands of wires, dual and solo cuts, a fuse dial, equipment cards and personal items.',''];
  for(const r of RULES){if(r.sec!==cur){cur=r.sec;out.push('','## '+cur,'')}out.push(`${r.n}. ${r.text}${r.src==='G'?' *(G)*':''}${r.how?' *('+r.how+')*':''}`)}
  out.push('','## Not covered by the engine test','',
  '- Communication rules (no talking about your hand, no recalling earlier turns, allowed table talk): enforced by players at a real table; the browser build shows all public information permanently and has no chat to police.',
  '- Mission-specific rules for missions 9 to 66 (gates, timers, oxygen, robot, bunker, audio): outside the base rulebook; they are covered by the mission sweeps, not by this checklist.','');
  console.log(out.join('\n'));process.exit(0)}
let pass=0;const failed=[];
for(const r of RULES){try{r.fn();pass++}catch(e){failed.push(r.n);console.log(`FAIL rule ${r.n} [${r.sec}] ${r.text.slice(0,70)}: ${String(e.message).split('\n')[0]}`)}}
console.log(`logic-test: ${RULES.length} rules, ${pass} pass, ${failed.length} fail${failed.length?' (rules '+failed.join(', ')+')':''}`);
process.exit(failed.length?1:0);
